function drawCross(ctx,x,y,scale=1){const l=clamp(+pref.length||0,0,25)*scale,g=clamp(+pref.gap||0,0,18)*scale,w=clamp(+pref.thickness||1,1,6)*scale;ctx.save();ctx.globalAlpha=clamp(+pref.opacity||100,10,100)/100;const lines=[[x-g-l,y,x-g,y],[x+g,y,x+g+l,y],[x,y-g-l,x,y-g],[x,y+g,x,y+g+l]];for(const [color,th] of [...(pref.outline?[['#000000',w+2*scale]]:[]),[safeHex(pref.cross,'#ffffff'),w]]){ctx.strokeStyle=color;ctx.lineWidth=th;ctx.beginPath();for(const [a,b,c,d] of lines){ctx.moveTo(a,b);ctx.lineTo(c,d)}ctx.stroke();if(pref.dot){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,th/2,0,2*Math.PI);ctx.fill()}}ctx.restore()}
