const cfg=()=>{const game=val('Game'),dpi=+val('Dpi'),sens=+val('Sens'),cm=cm360(dpi,sens,game),standard=val('Format')==='ranked';return{game,dpi,sens,cm,fov:+val('Fov'),duration:+val('Duration'),vert:+val('Vert')/100,size:standard?1:+val('Size')/100,speed:standard?1:+val('Speed')/100,count:standard?sel.count:+val('Count'),standard,scenario:sel.key,seed:Math.floor(Math.random()*4294967296)}};
function physical(){const c=cfg();get('SensLabel').firstChild.textContent=c.game==='fivem'?'cm/360 medidos':'Sensibilidad';text(get('Physical'),finite(c.cm)&&c.cm>0?`${c.cm.toFixed(2)} cm/360 · ${(c.cm/2).toFixed(2)} cm/180${c.game==='fivem'?' · calibrado manualmente':''}`:'Introduce DPI y sensibilidad válidos.')}
function useSetup(){const s=currentSetup();get('Game').value=s.game;get('Dpi').value=s.dpi;get('Sens').value=s.sens;get('Fov').value=s.game==='valorant'?103:90;physical()}
get('Game').onchange=()=>{get('Sens').value=GAMES[val('Game')].default;physical()};['Dpi','Sens'].forEach(k=>get(k).oninput=physical);get('Use').onclick=useSetup;get('Style').onclick=()=>go('appearance');get('Format').onchange=()=>{for(const k of ['Size','Speed','Count'])get(k).disabled=val('Format')==='ranked'};
function recordBest(s){const h=history.filter(x=>x.source===key&&x.renderer===(three?(renderGL?'webgl':'projection'):'canvas2d')&&x.scenario===s.key&&x.standard&&x.duration===+val('Duration')&&x.fov===+val('Fov')&&x.vertical===+val('Vert')/100&&x.complete&&finite(x.score));return h.length?Math.max(...h.map(x=>x.score)):null}
function choose(s){if(E.active||E.requesting)return;sel=s;text(get('Title'),s.name);text(get('Desc'),s.desc);get('Count').value=s.count;E.renderLibrary();drawIdle()}
E.renderLibrary=()=>{const l=get('Library'),f=val('Filter');l.replaceChildren();for(const s of catalog.filter(s=>f==='Todos'||f===s.cat||f==='Favoritos'&&fav.includes(key+':'+s.key))){const b=make('div','comp-scenario'+(s.key===sel.key?' selected':''));const pick=make('button','comp-select',thumbnail(s)+`<b>${s.name}</b><small>${s.cat} · ${s.radius<=1.25?'Precisión alta':'Normal'}</small>`);const record=make('small','');const best=recordBest(s);text(record,best===null?'Récord: —':'Récord: '+best.toFixed(1));pick.append(record);pick.onclick=()=>{choose(s);get('Arena').scrollIntoView({block:'center',behavior:pref.motion?'smooth':'auto'})};const star=make('button','comp-star',fav.includes(key+':'+s.key)?'★':'☆');star.title='Favorito';star.setAttribute('aria-label','Favorito '+s.name);star.onclick=()=>{const k=key+':'+s.key;fav=fav.includes(k)?fav.filter(x=>x!==k):[...fav,k];storeFav();E.renderLibrary()};b.append(pick,star);l.append(b)}if(!l.children.length)text(l,'No hay escenarios en esta categoría.')};get('Filter').onchange=E.renderLibrary;['Duration','Fov','Vert'].forEach(k=>get(k).addEventListener('change',E.renderLibrary));
function drawIdle(){if(!ctx)return;if(three){ctx.clearRect(0,0,cv.width,cv.height);if(renderGL)renderGL({cam:[0,0,0],yaw:0,pitch:0},[{pos:[-2,0,9],worldR:.5},{pos:[1,1,12],worldR:.55},{pos:[2,-.3,6],worldR:.4}],{fov:90});else{fallbackRoom(ctx,cv.width,cv.height,0,0);for(const [x,y,r] of [[340,270,27],[520,225,22],[645,290,35]])sphere2d(ctx,x,y,r)}drawCross(ctx,cv.width/2,cv.height/2)}else{ctx.fillStyle=safeHex(pref.arena,'#0b0a14');ctx.fillRect(0,0,cv.width,cv.height);for(const [x,y] of [[cv.width*.25,cv.height*.3],[cv.width*.72,cv.height*.6],[cv.width*.55,cv.height*.23]]){ctx.fillStyle=safeHex(pref.target,'#ad7cff');ctx.beginPath();ctx.arc(x,y,15,0,Math.PI*2);ctx.fill()}drawCross(ctx,cv.width/2,cv.height/2)}}
function spawn(t,index=0){const c=run.c,s=run.s,R=run.rand,r=s.radius*c.size,sw=s.behavior==='switch',near=s.behavior==='micro',turn=s.behavior==='turn';let a=(R()-.5)*(near?12:c.fov*.76),b=(R()-.5)*(near?9:c.fov*.42);if(sw){run.side*=-1;a=run.side*c.fov*.32;b=(R()-.5)*c.fov*.25}if(turn){run.side*=-1;a=run.side*180;b=0}if(three){const distance=s.key==='close'?5:s.key==='long'?15:6+R()*7,worldR=Math.tan(r*deg)*distance,dir=vec(run.yaw+a,clamp(run.pitch+b,-75,75));const pos=dir.map((v,i)=>run.cam[i]+v*distance);return{a,b,pos,base:[...pos],worldR,phase:R()*6.28,born:t,dir:R()<.5?-1:1}}const x=clamp(cv.width/2+a/c.fov*cv.width,25,cv.width-25),y=clamp(cv.height/2-b/c.fov*cv.width,25,cv.height-25);const px=Math.max(5,r/c.fov*cv.width);return{x,y,bx:x,by:y,r:px,phase:R()*6.28,born:t,vx:(R()<.5?-1:1)*150*c.speed,vy:(R()<.5?-1:1)*115*c.speed,dirAt:t+450+R()*550}}
function moveTargets(t,dt){const b=run.s.behavior,speed=run.c.speed;if(b==='reaction'&&!run.targets.length&&t>=run.nextAt)run.targets.push(spawn(t));if(!['smooth','reactive','moving','horizontal','vertical'].includes(b))return;for(const x of run.targets){const e=(t-x.born)/1000*speed;if(three){if(b==='reactive'){const step=Math.floor(e*1.65);x.pos[0]=x.base[0]+Math.sin(e*3+step*1.2)*2.6;x.pos[1]=x.base[1]+Math.sin(e*1.2)*.65}else if(b==='vertical'){x.pos[1]=x.base[1]+Math.abs(Math.sin(e*2))*3-1.3}else{x.pos[0]=x.base[0]+Math.sin(e*1.7+x.phase)*2.7;x.pos[1]=x.base[1]+Math.sin(e*1.1)*.7}}else if(b==='reactive'){if(t>=x.dirAt){if(run.rand()<.8)x.vx*=-1;if(run.rand()<.65)x.vy*=-1;x.dirAt=t+300+run.rand()*650}x.x+=x.vx*dt/1000;x.y+=x.vy*dt/1000;if(x.x<35||x.x>cv.width-35){x.vx*=-1;x.x=clamp(x.x,35,cv.width-35)}if(x.y<35||x.y>cv.height-35){x.vy*=-1;x.y=clamp(x.y,35,cv.height-35)}}else{const ampX=b==='vertical'?0:Math.min(cv.width*.29,x.bx-25,cv.width-x.bx-25),ampY=b==='horizontal'?0:Math.min(cv.height*.24,x.by-25,cv.height-x.by-25);x.x=x.bx+Math.sin(e*(b==='moving'?2.8:1.8)+x.phase)*ampX;x.y=x.by+Math.sin(e*1.6+x.phase*.7)*ampY}}}
